 'A': lambda x: x[0]+x[1]*T**x[2]/e+x[3]*np.log(e)*T**x[4],
 'B': lambda x: x[0]/e+x[1]*T**x[2]*np.exp(-x[3]*e)+x[4]*T**x[5],
 'C': lambda x: x[0]*T**x[1]*e**x[2]+x[3]/e+x[4]*T**x[5],
 'E': lambda x: x[0]*(T/e)**x[1]+x[2]*e+x[3]*T**x[4]+x[5],
}
rng=np.random.default_rng(1)
out={}
for name,f in fams.items():
